mapper.update:
update screening_apply
resident_name = #{residentName}, id_card = #{idCard}, phone = #{phone}, apply_date = #{applyDate}, apply_type = #{applyType}, disease_history = #{diseaseHistory}, current_medication = #{currentMedication}, apply_reason = #{applyReason}, audit_status = #{auditStatus}, audit_opinion = #{auditOpinion}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where id = #{id}

mapper.select:
select mp.person_id as mp_person_id, mp.person_name as mp_person_name, mp.card_id as mp_card_id, mp.gender_source_value as mp_gender_source_value, mp.sex as mp_sex, mp.phone_number as mp_phone_number, mp.create_time as mp_create_time, mp.update_time as mp_update_time, t.id, t.id_card, t.phone, t.create_time, t.update_time, t.remark, t.apply_date, t.apply_type, t.disease_history, t.current_medication, t.apply_reason, t.audit_status, t.audit_opinion from screening_apply t
and mp.person_name like concat('%', #{personName}, '%') and mp.card_id = #{cardId} and t.apply_type like concat('%', #{applyType}, '%') and t.audit_status = #{auditStatus}
order by t.id desc
